-- H2-04 Pharma OA workflow-linked business records. Normal uninstall policy: retain.
CREATE TABLE IF NOT EXISTS pharma_oa_contracts (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, title VARCHAR(255) NOT NULL, party_type VARCHAR(32) NOT NULL, party_id VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, workflow_instance_id VARCHAR(64) NOT NULL, owner_id VARCHAR(64) NOT NULL, approver_id VARCHAR(64) NOT NULL, amount NUMERIC(18,2) NOT NULL, currency VARCHAR(16) NOT NULL, effective_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_contracts_number ON pharma_oa_contracts(number); CREATE INDEX IF NOT EXISTS idx_pharma_contracts_party_status ON pharma_oa_contracts(party_type,party_id,status); CREATE INDEX IF NOT EXISTS idx_pharma_contracts_expiry ON pharma_oa_contracts(expires_at,status);
CREATE TABLE IF NOT EXISTS pharma_oa_quality_complaints (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, title VARCHAR(255) NOT NULL, customer_id VARCHAR(64) NOT NULL, product_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, workflow_instance_id VARCHAR(64) NOT NULL, reporter_id VARCHAR(64) NOT NULL, handler_id VARCHAR(64) NOT NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_complaints_number ON pharma_oa_quality_complaints(number); CREATE INDEX IF NOT EXISTS idx_pharma_complaints_status_product ON pharma_oa_quality_complaints(status,product_id); CREATE INDEX IF NOT EXISTS idx_pharma_complaints_batch ON pharma_oa_quality_complaints(batch_id);
CREATE TABLE IF NOT EXISTS pharma_oa_drug_recalls (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, title VARCHAR(255) NOT NULL, product_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, source_complaint_id VARCHAR(64) NOT NULL DEFAULT '', status VARCHAR(32) NOT NULL, initiated_by VARCHAR(64) NOT NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_recalls_number ON pharma_oa_drug_recalls(number); CREATE INDEX IF NOT EXISTS idx_pharma_recalls_batch_status ON pharma_oa_drug_recalls(batch_id,status);
CREATE TABLE IF NOT EXISTS pharma_oa_customer_follow_ups (id VARCHAR(64) PRIMARY KEY, customer_id VARCHAR(64) NOT NULL, customer_code VARCHAR(128) NOT NULL, customer_name VARCHAR(255) NOT NULL, owner_id VARCHAR(64) NOT NULL, organization_id VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, scheduled_at TIMESTAMPTZ NOT NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE INDEX IF NOT EXISTS idx_pharma_followups_scope_status ON pharma_oa_customer_follow_ups(organization_id,owner_id,status); CREATE INDEX IF NOT EXISTS idx_pharma_followups_customer_time ON pharma_oa_customer_follow_ups(customer_id,scheduled_at);
CREATE TABLE IF NOT EXISTS pharma_oa_sales_opportunities (id VARCHAR(64) PRIMARY KEY, title VARCHAR(255) NOT NULL, customer_id VARCHAR(64) NOT NULL, customer_code VARCHAR(128) NOT NULL, customer_name VARCHAR(255) NOT NULL, owner_id VARCHAR(64) NOT NULL, organization_id VARCHAR(64) NOT NULL, stage VARCHAR(32) NOT NULL, expected_amount_cents BIGINT NOT NULL, estimated_close_date TIMESTAMPTZ NOT NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE INDEX IF NOT EXISTS idx_pharma_opportunities_scope_stage ON pharma_oa_sales_opportunities(organization_id,owner_id,stage); CREATE INDEX IF NOT EXISTS idx_pharma_opportunities_customer ON pharma_oa_sales_opportunities(customer_id);
CREATE TABLE IF NOT EXISTS pharma_oa_payment_plans (id VARCHAR(64) PRIMARY KEY, sales_order_id VARCHAR(64) NOT NULL, sales_order_number VARCHAR(128) NOT NULL, customer_id VARCHAR(64) NOT NULL, owner_id VARCHAR(64) NOT NULL, order_total_cents BIGINT NOT NULL, amount_cents BIGINT NOT NULL, paid_amount_cents BIGINT NOT NULL, status VARCHAR(32) NOT NULL, due_at TIMESTAMPTZ NOT NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_payment_plan_order ON pharma_oa_payment_plans(sales_order_id); CREATE INDEX IF NOT EXISTS idx_pharma_payment_plan_due_status ON pharma_oa_payment_plans(status,due_at);
CREATE TABLE IF NOT EXISTS pharma_oa_invoice_records (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, sales_order_id VARCHAR(64) NOT NULL, sales_order_number VARCHAR(128) NOT NULL, customer_id VARCHAR(64) NOT NULL, owner_id VARCHAR(64) NOT NULL, order_total_cents BIGINT NOT NULL, amount_cents BIGINT NOT NULL, status VARCHAR(32) NOT NULL, issued_at TIMESTAMPTZ NOT NULL, voided_at TIMESTAMPTZ NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_invoices_number ON pharma_oa_invoice_records(number); CREATE INDEX IF NOT EXISTS idx_pharma_invoices_order_status ON pharma_oa_invoice_records(sales_order_id,status);
CREATE TABLE IF NOT EXISTS pharma_oa_payment_reminder_jobs (id VARCHAR(64) PRIMARY KEY, status VARCHAR(32) NOT NULL, recipient_id VARCHAR(64) NOT NULL, owner_id VARCHAR(64) NOT NULL DEFAULT '', initiated_by VARCHAR(64) NOT NULL, last_run_by VARCHAR(64) NOT NULL, retry_count INTEGER NOT NULL, error VARCHAR(1024) NOT NULL DEFAULT '', started_at TIMESTAMPTZ NULL, completed_at TIMESTAMPTZ NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE INDEX IF NOT EXISTS idx_pharma_payment_reminder_jobs_status_created ON pharma_oa_payment_reminder_jobs(status,created_at);
CREATE TABLE IF NOT EXISTS pharma_oa_inventory_alerts (id VARCHAR(64) PRIMARY KEY, type VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, balance_id VARCHAR(64) NOT NULL, product_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, recipient_id VARCHAR(64) NOT NULL, notification_id VARCHAR(128) NOT NULL, last_seen_at TIMESTAMPTZ NOT NULL, resolved_at TIMESTAMPTZ NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_inventory_alert_position ON pharma_oa_inventory_alerts(type,balance_id); CREATE INDEX IF NOT EXISTS idx_pharma_inventory_alerts_status_seen ON pharma_oa_inventory_alerts(status,last_seen_at);
CREATE TABLE IF NOT EXISTS pharma_oa_inventory_alert_jobs (id VARCHAR(64) PRIMARY KEY, status VARCHAR(32) NOT NULL, idempotency_key VARCHAR(191) NOT NULL, retry_count INTEGER NOT NULL, error VARCHAR(1024) NOT NULL DEFAULT '', started_at TIMESTAMPTZ NULL, completed_at TIMESTAMPTZ NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_alert_jobs_idempotency ON pharma_oa_inventory_alert_jobs(idempotency_key); CREATE INDEX IF NOT EXISTS idx_pharma_alert_jobs_status_created ON pharma_oa_inventory_alert_jobs(status,created_at);
CREATE TABLE IF NOT EXISTS pharma_oa_report_export_jobs (id VARCHAR(64) PRIMARY KEY, report_type VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, owner_id VARCHAR(64) NOT NULL, idempotency_key VARCHAR(191) NOT NULL, retry_count INTEGER NOT NULL, file_id VARCHAR(64) NOT NULL DEFAULT '', error VARCHAR(1024) NOT NULL DEFAULT '', started_at TIMESTAMPTZ NULL, completed_at TIMESTAMPTZ NULL, payload_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT ''); CREATE UNIQUE INDEX IF NOT EXISTS uk_pharma_export_jobs_idempotency ON pharma_oa_report_export_jobs(idempotency_key); CREATE INDEX IF NOT EXISTS idx_pharma_export_jobs_status_created ON pharma_oa_report_export_jobs(status,created_at);
